events.syntax:
if thread.role.executable and thread.tags != updated.tags:
    channels = {**previous_channels, **self.catalog.read().views(self.registry.all_threads())}
    for channel in channels.values():
        if channel.view is not None:
            continue
        before, after = (channel.matches(thread.tags), channel.matches(updated.tags))
        if before != after:
            change = MembershipChange.JOINED if after else MembershipChange.LEFT
            self.bus.publisher.publish_ordinary(Message(thread.name, channel.name, f'{thread.name} {change.value} {channel.name}', MessageType.INFO, member

if reserved is not None and (not reserved.sent_owner_admission_generation.matches(self.admission_generation)):
    if prior is None or injected_seq > prior.injected_seq:
        return False
    raise IdentityConflict('current cursor input admission differs')

if self.thread.auto_title_pending:
    instruction = InstructionFile.read('automatic-title.md')
    self.context = self.context.prepend(AutomaticTitleSegment(provenance=(instruction.source, OwnerProvenance(self.thread.incarnation, self.turn_id)), instruction=instruction))

if (active_goal := self.thread.active_goal):
    permission = ContinuationGoalPermission(active_goal)
else:
    permission = InactiveGoalPermission()

if thread.process_alive:
    if not status.active:
        raise RelationViolationError('Stopped owner has not exited yet.')
    return OwnerStartResult(thread.name, thread.pid, False)

if thread.pid == os.getpid():
    caller = os.environ.get('PI_AGENT_ID') or os.environ.get('AGENT_COMMS_THREAD')
    if caller and self.registry.require(caller).name == thread.name:
        self._release_current_owner_unlocked(thread.name)
    else:
        self.registry.unregister(thread.name)
    return

if caller and self.registry.require(caller).name == thread.name:
    self._release_current_owner_unlocked(thread.name)
else:
    self.registry.unregister(thread.name)

if snapshot.aliases.get(name, name) == viewer and created == thread.created_at:
    conversation = Conversation.from_wire(raw)
    if conversation.current(snapshot):
        seen.update(sequences)

if before != change.thread.goal:
    history = GoalHistoryStore(self.store.path)
    intent = history.begin(change.thread.created_at, before, change.thread.goal)

if any((existing.created_at == thread.created_at for existing in self.threads.values())):
    if not thread._generated_created_at:
        raise RelationViolationError('Registry creation identities collide.')
    used = {existing.created_at for existing in self.threads.values()}
    candidate = float(thread.created_at)
    while candidate in used:
        candidate = math.nextafter(candidate, math.inf)
    if not math.isfinite(candidate):
        raise RelationViolationError('Registry creation identities collide.')
    thread = replace(thread, created_at=candidate)

if canonical(message.sender) == thread.name:
    key = canonical(message.target) if not is_channel_target(message.target) else message.target
    outbound.setdefault(key, entry(message.target, message=message, detail=detail))
elif delivery.delivers(message.sender, message.target):
    inbound.setdefault(canonical(message.sender), entry(message.sender, message=message, detail=detail))
    if is_channel_target(message.target):
        inbound.setdefault(message.target, entry(message.target, message=message, detail=detail))

if self.titles.get(session_id) != name or self.display_titles.get(session_id) != thread.title:
    await self.runtime.session_update(session_id=session_id, update=SessionInfoUpdate(session_update='session_info_update', title=thread.title or name, field_meta=await self.metadata(name, session_id=session_id)))
    self.titles[session_id], self.display_titles[session_id] = (name, thread.title)

if self.worktrees.get(session_id) != thread.worktree:
    await self.runtime.session_update(session_id=session_id, update=SessionInfoUpdate(session_update='session_info_update', field_meta=await self.metadata(name, session_id=session_id)))
    self.worktrees[session_id] = thread.worktree
